SELECT seat_id AS seatId, seat_no AS seatNo, seat_type AS SeatType, is_available AS available, is_upgraded AS upgraded
FROM seats 
WHERE seat_id = #{seatId}

SELECT seat_id AS seatId, seat_no AS seatNo, seat_type AS SeatType, is_available AS available, is_upgraded AS upgraded
FROM seats 
WHERE flight_id = #{flightId}
